import ast
import os
from pathlib import Path
from collections import defaultdict

# Build a dependency graph
imports = defaultdict(set)

for py_file in Path("./python/synapse").glob("**/*.py"):
    if py_file.name == "__init__.py":
        continue

    relative_path = str(py_file.relative_to("./python/synapse")).replace("\\", "/").replace(".py", "")
    module_name = relative_path.replace("/", ".")

    try:
        with open(py_file, 'r', encoding='utf-8') as f:
            tree = ast.parse(f.read())

        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom):
                if node.module and node.module.startswith("synapse"):
                    imports[module_name].add(node.module.replace("synapse.", ""))
            elif isinstance(node, ast.Import):
                for alias in node.names:
                    if alias.name.startswith("synapse"):
                        imports[module_name].add(alias.name.replace("synapse.", ""))
    except:
        pass

# Check for cycles
def find_cycle(start, visited, rec_stack, graph):
    visited.add(start)
    rec_stack.add(start)

    for neighbor in graph.get(start, set()):
        if neighbor not in visited:
            if find_cycle(neighbor, visited, rec_stack, graph):
                return True
        elif neighbor in rec_stack:
            return True

    rec_stack.remove(start)
    return False

cycles = []
for module in imports:
    if find_cycle(module, set(), set(), imports):
        cycles.append(module)

if cycles:
    print(f"Found {len(cycles)} modules in circular dependencies:")
    for c in sorted(cycles):
        print(f"  - {c}")
else:
    print("No circular imports detected")
