import ast
from pathlib import Path
from collections import defaultdict

# Scan all Python files to find defined functions and references
defined_funcs = defaultdict(set)
referenced_names = defaultdict(set)
all_imports = defaultdict(set)

for py_file in Path("./python/synapse").glob("**/*.py"):
    module_name = str(py_file.relative_to("./python/synapse")).replace("\\", "/").replace(".py", "").replace("/", ".")

    try:
        with open(py_file, 'r', encoding='utf-8') as f:
            tree = ast.parse(f.read())

        # Find defined functions and classes
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if not node.name.startswith('_'):  # Skip private methods
                    defined_funcs[module_name].add(node.name)
            elif isinstance(node, ast.ClassDef):
                if not node.name.startswith('_'):
                    defined_funcs[module_name].add(node.name)
            elif isinstance(node, ast.Name):
                referenced_names[module_name].add(node.id)
            elif isinstance(node, ast.Attribute):
                if isinstance(node.value, ast.Name):
                    referenced_names[module_name].add(node.value.id)
    except:
        pass

# Find potentially dead functions (defined but never referenced)
potentially_dead = []
for module, funcs in defined_funcs.items():
    refs = referenced_names.get(module, set())
    for func in funcs:
        if func not in refs and func not in ["main", "cli", "run"]:
            # Check if it's used anywhere across the codebase
            used_elsewhere = False
            for other_module, other_refs in referenced_names.items():
                if func in other_refs:
                    used_elsewhere = True
                    break

            if not used_elsewhere:
                potentially_dead.append((module, func))

if potentially_dead[:10]:
    print("Potentially dead functions (sample):")
    for module, func in potentially_dead[:10]:
        print(f"  {module}.{func}")
    print(f"\nTotal: {len(potentially_dead)} (showing first 10)")
else:
    print("No obvious dead functions detected")
