    total_funcs = 0

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if not node.name.startswith('_'):
                total_funcs += 1
                if not ast.get_docstring(node):
                    funcs_no_doc.append(node.name)

    pct = ((total_funcs - len(funcs_no_doc)) / total_funcs * 100) if total_funcs > 0 else 0
    print(f"{file_path}: {total_funcs - len(funcs_no_doc)}/{total_funcs} functions documented ({pct:.1f}%)")
    if funcs_no_doc and len(funcs_no_doc) <= 5:
        for f in funcs_no_doc:
            print(f"    missing: {f}()")
