import re
from pathlib import Path
from collections import defaultdict

# Find magic numbers (numeric literals) that appear frequently
magic_numbers = defaultdict(list)

for py_file in Path("./python/synapse").glob("**/*.py"):
    with open(py_file, 'r', encoding='utf-8') as f:
        content = f.read()

    # Look for numeric literals in assignments that aren't in docstrings
    lines = content.split('\n')
    for i, line in enumerate(lines):
        # Skip comments and docstrings
        if line.strip().startswith('#') or line.strip().startswith('"""') or line.strip().startswith("'''"):
            continue

        # Look for common timeout/limit patterns
        if re.search(r'timeout.*?(\d+\.?\d*)', line):
            match = re.search(r'timeout.*?=\s*(\d+\.?\d*)', line)
            if match:
                num = match.group(1)
                magic_numbers[f"timeout={num}"].append(str(py_file.relative_to("./python/synapse")))

        if re.search(r'limit.*?=\s*(\d+)', line):
            match = re.search(r'limit.*?=\s*(\d+)', line)
            if match:
                num = match.group(1)
                magic_numbers[f"limit={num}"].append(str(py_file.relative_to("./python/synapse")))

# Find repeated patterns
repeated = {k: v for k, v in magic_numbers.items() if len(v) > 2}
if repeated:
    print("Repeated magic numbers (hardcoded config):")
    for num_pattern, files in sorted(repeated.items()):
        print(f"\n  {num_pattern} appears in {len(set(files))} files:")
        for f in sorted(set(files))[:5]:
            print(f"    - {f}")
        if len(set(files)) > 5:
            print(f"    ... and {len(set(files)) - 5} more")
else:
    print("No obvious repeated magic numbers found")
