import ast
from pathlib import Path

# Find functions with many parameters
big_param_funcs = []

for py_file in Path("./python/synapse").glob("**/*.py"):
    try:
        with open(py_file, 'r', encoding='utf-8') as f:
            tree = ast.parse(f.read())

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                param_count = len(node.args.args)
                if param_count > 5:
                    docstring = ast.get_docstring(node)
                    has_params_doc = docstring and ("Args:" in docstring or "Parameters:" in docstring)
                    big_param_funcs.append({
                        'file': str(py_file.relative_to("./python/synapse")),
                        'name': node.name,
                        'params': param_count,
                        'has_doc': bool(has_params_doc),
                        'line': node.lineno,
                    })
    except:
        pass

# Find undocumented multi-param functions
